INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Mache ich hier Verbesserungen nur einmal?', 2, '[{"text": "Nein", "correct": true, "because": "Fortlaufende Anpassung"}, {"text": "Ja", "correct": false, "because": "Iterativer Prozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit diesen Verbesserungen?', 3, '[{"text": "Code-Optimierung", "correct": true, "because": "Effizienz und Lesbarkeit steigern"}, {"text": "Einmalige Fertigstellung", "correct": false, "because": "Fortlaufend nötig"}, {"text": "Dokumentation", "correct": false, "because": "Nebenrangig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte werden hier optimiert?', 5, '[{"text": "Design", "correct": true, "because": "Struktur verbessern"}, {"text": "Code", "correct": true, "because": "Qualität erhöhen"}, {"text": "Statische Lösungen", "correct": false, "because": "Dynamische Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Refactoring gehört dazu. b) Design bleibt unverändert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Design wird optimiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei diesen Verbesserungen?', 4, '[{"text": "Code-Optimierung", "correct": false, "because": "Kern der Anpassung"}, {"text": "Design", "correct": false, "because": "Struktur verbessern"}, {"text": "Einmalige Lösungen", "correct": true, "because": "Fortlaufend nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Refactoring hier unwichtig ist?', 2, '[{"text": "Nein", "correct": true, "because": "Zentral für Code-Verbesserung"}, {"text": "Ja", "correct": false, "because": "Wichtiger Bestandteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich, um den Code zu verbessern?', 3, '[{"text": "Refactoring", "correct": true, "because": "Code-Struktur optimieren"}, {"text": "Design ignorieren", "correct": false, "because": "Design wird angepasst"}, {"text": "Einmalige Änderung", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bringen diese Optimierungen?', 5, '[{"text": "Bessere Lesbarkeit", "correct": true, "because": "Code klarer gestalten"}, {"text": "Wartbarkeit", "correct": true, "because": "Design und Code anpassbar"}, {"text": "Statische Struktur", "correct": false, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Design wird optimiert. b) Code bleibt gleich. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Code wird angepasst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich hier nicht unbedingt?', 4, '[{"text": "Refactoring", "correct": false, "because": "Code verbessern"}, {"text": "Design-Anpassung", "correct": false, "because": "Struktur optimieren"}, {"text": "Feste Architektur", "correct": true, "because": "Flexibilität zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Bleibt der Code hier unverändert?', 2, '[{"text": "Nein", "correct": true, "because": "Code wird optimiert"}, {"text": "Ja", "correct": false, "because": "Fortlaufende Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Elemente fördern die Qualität?', 4, '[{"text": "Code-Optimierung", "correct": true, "because": "Effizienz steigern"}, {"text": "Design-Verbesserung", "correct": true, "because": "Struktur klarer"}, {"text": "Einmalige Fixes", "correct": false, "because": "Iterativ nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Verbesserungen hier selten sind. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Fortlaufend durchgeführt"}, {"text": "Ja", "correct": false, "because": "Iterativer Ansatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei diesen Anpassungen?', 3, '[{"text": "Design und Code", "correct": true, "because": "Beides optimieren"}, {"text": "Statische Lösungen", "correct": false, "because": "Flexibilität zählt"}, {"text": "Keine Änderungen", "correct": false, "because": "Verbesserung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Refactoring verbessert Code. b) Design wird ignoriert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Design wird angepasst"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Stärken haben diese Verbesserungen?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Anpassung möglich"}, {"text": "Qualität", "correct": true, "because": "Code und Design optimiert"}, {"text": "Statische Ergebnisse", "correct": false, "because": "Dynamik zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist hier weniger wichtig?', 3, '[{"text": "Code-Optimierung", "correct": false, "because": "Kern der Verbesserung"}, {"text": "Design", "correct": false, "because": "Struktur zentral"}, {"text": "Feste Struktur", "correct": true, "because": "Anpassung nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Refactoring hier Kosmetik?', 3, '[{"text": "Nein", "correct": true, "because": "Funktionale Verbesserung"}, {"text": "Ja", "correct": false, "because": "Struktur und Effizienz"}]'),
